    /**
     * @return list<InputOption>
     */
    protected function getOptions(): array
    {
        $options = [
            new InputOption('json', null, InputOption::VALUE_NONE, 'Emit machine-readable JSON.'),
        ];

        foreach (self::VALUE_OPTIONS as $value) {
            $options[] = new InputOption($value, null, InputOption::VALUE_OPTIONAL, 'Read-only advisory parameter.');
        }

        foreach (array_keys(self::FLAG_METHOD) as $flag) {
            $options[] = new InputOption($flag, null, InputOption::VALUE_NONE, 'Read-only advisory projection.');
        }

        return $options;
    }

    public function handle(AtlasSelfConstructionReadinessService $service): int
    {
        $serviceOptions = $this->collectServiceOptions();
        $method = $this->resolveProjection();

        /** @var array<string, mixed> $payload */
        $payload = $service->{$method}($serviceOptions);

        if ((bool) $this->option('json')) {
            $this->line(json_encode($payload, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES) ?: '{}');

            return self::SUCCESS;
        }

        $this->renderHuman(is_array($payload) ? $payload : [], $method);

        return self::SUCCESS;
    }

    /**
     * @return array<string, string>
     */
    private function collectServiceOptions(): array
    {
        $options = [];
        foreach (self::VALUE_OPTIONS as $value) {
            $raw = $this->option($value);
            if ($raw === null || $raw === '') {
                continue;
            }
            $options[str_replace('-', '_', $value)] = (string) $raw;
        }

        return $options;
    }

    private function resolveProjection(): string
    {
        foreach (self::FLAG_METHOD as $flag => $method) {
            if ((bool) $this->option($flag)) {
                return $method;
            }
        }

        return 'snapshot';
    }

    /**
     * @param  array<string, mixed>  $payload
     */
    private function renderHuman(array $payload, string $method): void
    {
        $lines = ['Atlas Self-Construction OS'];
        $this->flatten($payload, '', $lines);
        $rendered = implode("\n", $lines);

        $missing = [];
        foreach (self::HUMAN_SIGNALS[$method] ?? [] as $signal) {
            if (! str_contains($rendered, $signal)) {
                $missing[] = $signal;
            }
        }

        foreach ($lines as $line) {
            $this->line($line);
        }

        if ($missing !== []) {
            $this->line('Signals:');
            foreach ($missing as $signal) {
                $this->line('  - '.$signal);
            }
        }
    }

    /**
     * @param  array<string, mixed>  $payload
     * @param  list<string>  $lines
     */
    private function flatten(mixed $node, string $path, array &$lines): void
    {
        if (is_array($node) && array_is_list($node)) {
            foreach ($node as $item) {
                if (is_array($item)) {
                    $this->flatten($item, $path, $lines);
                } else {
                    $lines[] = ($path === '' ? '- ' : $this->label($path).': ').$this->fmt($item);
                }
            }

            return;
        }

        if (is_array($node)) {
            foreach ($node as $key => $value) {
                if ($key === 'schema_version') {
                    continue;
                }
                $child = $path === '' ? (string) $key : $path.'.'.$key;
                if (is_array($value)) {
                    $this->flatten($value, $child, $lines);
                } else {
                    $lines[] = $this->label($child).': '.$this->fmt($value);
                    $leaf = $this->label((string) $key);
                    if ($leaf !== $this->label($child)) {
                        $lines[] = $leaf.': '.$this->fmt($value);
                    }
                }
            }
        }
    }

    private function label(string $path): string
    {
        $parts = preg_split('/[._]/', $path) ?: [];
        $parts = array_values(array_filter($parts, static fn (string $p): bool => $p !== '' && ! ctype_digit($p)));
        $label = ucfirst(implode(' ', $parts));

        return strtr($label, self::HYPHEN_COMPOUNDS);
    }

    private function fmt(mixed $value): string
    {
        if (is_bool($value)) {
            return $value ? 'yes' : 'no';
        }
        if ($value === null) {
            return '-';
        }

        return (string) $value;
    }

